What does this program print?

fn main() {
    let mut cage = vec!["SH-1", "SH-2", "SH-3", "SH-4", "SH-5"];
    let delivered = ["SH-2", "SH-3", "SH-5"];
    let mut i = 0;
    while i < cage.len() {
        if delivered.contains(&cage[i]) {
            cage.remove(i);
        }
        i += 1;
    }
    println!("{cage:?}");
}

